import{_ as t,o,c as n,a3 as a}from"./chunks/framework.DMtjdCb-.js";const i="/help/assets/windows-release.en.CS-BMxLZ.png",u=JSON.parse('{"title":"1. Desktop setup","description":"","frontmatter":{},"headers":[],"relativePath":"en/desktop.md","filePath":"en/desktop.md"}'),s={name:"en/desktop.md"};function r(l,e,h,d,c,p){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="_1-desktop-setup" tabindex="-1">1. Desktop setup <a class="header-anchor" href="#_1-desktop-setup" aria-label="Permalink to &quot;1. Desktop setup&quot;">​</a></h1><p>This chapter gets AnimeMachine running in your browser. Connect qBittorrent or Ani-RSS when you want downloads; to play files you already have, <a href="./collections.html">add a media folder</a>.</p><h2 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows {#windows}&quot;">​</a></h2><ol><li>Open <a href="https://github.com/kyupi-git/animemachine/releases/latest" target="_blank" rel="noreferrer">Releases</a> and expand <strong>Assets</strong>.</li><li>Download the file ending in <code>release-windows.zip</code>.</li><li>Right-click it, choose <strong>Extract All</strong>, and extract it to a permanent folder such as <code>D:\\AnimeMachine</code>.</li><li>Open the extracted folder, double-click <strong><code>AnimeMachine.cmd</code></strong>, and leave the startup window open.</li><li>Open <strong><a href="http://localhost:8787" target="_blank" rel="noreferrer">http://localhost:8787</a></strong> in your browser.</li></ol><p><img src="'+i+'" alt="Windows startup window, extracted files, and home page" loading="lazy"></p><p><strong>Expected result:</strong> the AnimeMachine sign-in page appears. Find the initial username and password in the startup window, then continue to <a href="./first-use.html">First login</a>.</p><p>The package includes its runtime. Use the same launcher next time. Closing the startup window stops the app.</p><h2 id="macos-linux" tabindex="-1">macOS / Linux <a class="header-anchor" href="#macos-linux" aria-label="Permalink to &quot;macOS / Linux {#macos-linux}&quot;">​</a></h2><ol><li>Install <a href="https://www.python.org/downloads/" target="_blank" rel="noreferrer">Python 3.11 or later</a>.</li><li>Download the release for your operating system and processor from <a href="https://github.com/kyupi-git/animemachine/releases/latest" target="_blank" rel="noreferrer">Releases</a>, then extract it.</li><li>On macOS, open <strong><code>AnimeMachine-macOS.command</code></strong>. On Linux, open a terminal in the extracted folder and run:</li></ol><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./AnimeMachine-Linux.sh</span></span></code></pre></div><ol start="4"><li>Wait for startup, open <strong><a href="http://localhost:8787" target="_blank" rel="noreferrer">http://localhost:8787</a></strong>, and follow <a href="./first-use.html">First login</a>.</li></ol><table tabindex="0"><thead><tr><th>Processor</th><th>Release label</th></tr></thead><tbody><tr><td>Intel / AMD</td><td><code>x86_64</code></td></tr><tr><td>Apple silicon or other ARM PCs</td><td><code>arm64</code> or <code>aarch64</code></td></tr></tbody></table><p>The launcher installs required components. Leave the terminal open; press <code>Ctrl+C</code> to stop. If execution permission is missing, run <code>chmod +x AnimeMachine-Linux.sh</code> on Linux or <code>chmod +x AnimeMachine-macOS.command</code> on macOS in the extracted folder, then start again.</p><h2 id="open-it-from-another-device" tabindex="-1">Open it from another device <a class="header-anchor" href="#open-it-from-another-device" aria-label="Permalink to &quot;Open it from another device&quot;">​</a></h2><p>On the same LAN, use the <strong>LAN URL</strong> shown in the startup window, for example <code>http://192.168.1.20:8787</code>. On a phone, <code>localhost</code> means the phone itself; use the address of the computer running AnimeMachine.</p><h2 id="if-something-is-missing" tabindex="-1">If something is missing <a class="header-anchor" href="#if-something-is-missing" aria-label="Permalink to &quot;If something is missing&quot;">​</a></h2><ul><li><strong>No launcher:</strong> extract the entire ZIP first. Enable file-name extensions in File Explorer to check the name.</li><li><strong>Page will not open:</strong> keep the startup window running and use its actual port. See <a href="./troubleshooting.html#open-page">connection checks</a>.</li><li><strong>Moving the installation:</strong> stop the app, move the entire folder with <code>config.json</code> and <code>data</code>, then launch from its new location.</li></ul>',17)])])}const g=t(s,[["render",r]]);export{u as __pageData,g as default};
